// a is n x n cost matrix (double)
// returns assignment: ans[i] = column assigned to row i
void hungarian(int n, double *a, int *ans) {
    double *u = calloc(n+1, sizeof(double));
    double *v = calloc(n+1, sizeof(double));
    int *p = malloc((n+1)*sizeof(int));
    int *way = malloc((n+1)*sizeof(int));
    for (int i=1; i<=n; i++) {
        p[0] = i;
        int j0 = 0;
        double *minv = malloc((n+1)*sizeof(double));
        int *used = calloc(n+1, sizeof(int));
        for (int j=0; j<=n; j++) minv[j] = INF;
        do {
            used[j0] = 1;
            int i0 = p[j0];
            double delta = INF;
            int j1 = -1;
            for (int j=1; j<=n; j++) {
                if (!used[j]) {
                    double cur = a[(i0-1)*n + (j-1)] - u[i0] - v[j];
                    if (cur < minv[j]) { minv[j] = cur; way[j] = j0; }
                    if (minv[j] < delta) { delta = minv[j]; j1 = j; }
                }
            }
            for (int j=0; j<=n; j++) {
                if (used[j]) { u[p[j]] += delta; v[j] -= delta; }
                else minv[j] -= delta;
            }
            j0 = j1;
        } while (p[j0] != 0);
        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0);
    }
    for (int j=1; j<=n; j++) ans[p[j]-1] = j-1;
}
```

