```c
#include <stdlib.h>
#include <string.h>
#include <float.h>

#define BIG DBL_MAX

double lapjv(int dim, double *assigncost, int *rowsol, int *colsol, double *u, double *v) {
    int *free, *collist, *matches, *pred;
    double *d;
    int i, imin, numfree, numassigned, i0, freerow, j, j1, j2, endofpath, last, low, up;
    double min, h, umin, usub, v2;

    free = malloc(dim * sizeof(int));
    collist = malloc(dim * sizeof(int));
    matches = malloc(dim * sizeof(int));
    d = malloc(dim * sizeof(double));
    pred = malloc(dim * sizeof(int));

    // init
    for (i = 0; i < dim; i++) matches[i] = 0;

    // column reduction
    for (j = dim - 1; j >= 0; j--) {
        min = assigncost[0 * dim + j];
        imin = 0;
        for (i = 1; i < dim; i++) {
            if (assigncost[i * dim + j] < min) {
                min = assigncost[i * dim + j];
                imin = i;
            }
        }
        v[j] = min;
        if (++matches[imin] == 1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            colsol[j] = -1;
        }
    }

    // collect list of free rows
    numfree = 0;
    for (i = 0; i < dim; i++) {
        if (matches[i] == 0) {
            free[numfree++] = i;
        } else if (matches[i] == 1) {
            j1 = rowsol[i];
            min = BIG;
            for (j = 0; j < dim; j++) {
                if (j != j1 && assigncost[i*dim+j] - v[j] < min) {
                    min = assigncost[i*dim+j] - v[j];
                }
            }
            v[j1] -= min;
        }
    }

    // augmenting row reduction
    for (int loopcnt = 0; loopcnt < 2; loopcnt++) {
        int k = 0;
        int prvnumfree = numfree;
        numfree = 0;
        while (k < prvnumfree) {
            i = free[k];
            k++;
            // find min and second min
            umin = assigncost[i*dim] - v[0];
            j1 = 0;
            usub = BIG;
            for (j = 1; j < dim; j++) {
                h = assigncost[i*dim+j] - v[j];
                if (h < usub) {
                    if (h >= umin) {
                        usub = h;
                        j2 = j;
                    } else {
                        usub = umin;
                        umin = h;
                        j2 = j1;
                        j1 = j;
                    }
                }
            }
            i0 = colsol[j1];
            if (umin < usub) {
                v[j1] = v[j1] - (usub - umin);
            } else if (i0 >= 0) {
                j1 = j2;
                i0 = colsol[j1];
            }
            // (re)assign i to j1
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) {
                if (umin < usub) {
                    free[--k] = i0;
                } else {
                    free[numfree++] = i0;
                }
            }
        }
    }

    // augmenting solution for each free row
    for (int f = 0; f < numfree; f++) {
        freerow = free[f];
        // Dijkstra shortest augmenting path
        for (j = 0; j < dim; j++) {
            d[j] = assigncost[freerow*dim + j] - v[j];
            pred[j] = freerow;
            collist[j] = j;
        }
        low = 0;
        up = 0;
        int unassignedfound = 0;
        while (!unassignedfound) {
            if (up == low) {
                // find min in d
                last = low - 1;
                min = d[collist[up]];
                up++;
                for (k = up; k < dim; k++) {
                    j = collist[k];
                    h = d[j];
                    if (h <= min) {
                        if (h < min) {
                            up = low;
                            min = h;
                        }
                        collist[k] = collist[up];
                        collist[up] = j;
                        up++;
                    }
                }
                for (k = low; k < up; k++) {
                    j = collist[k];
                    if (colsol[j] < 0) {
                        endofpath = j;
                        unassignedfound = 1;
                        break;
                    }
                }
            }
            if (!unassignedfound) {
                j1 = collist[low];
                low++;
                i = colsol[j1];
                h = assigncost[i*dim + j1] - v[j1] - min;
                for (k = up; k < dim; k++) {
                    j = collist[k];
                    v2 = assigncost[i*dim + j] - v[j] - h;
                    if (v2 < d[j]) {
                        pred[j] = i;
                        if (v2 == min) {
                            if (colsol[j] < 0) {
                                endofpath = j;
                                unassignedfound = 1;
                                break;
                            } else {
                                collist[k] = collist[up];
                                collist[up] = j;
                                up++;
                            }
                        }
                        d[j] = v2;
                    }
                }
            }
        }
        // update column prices
        for (k = 0; k <= last; k++) {
            j1 = collist[k];
            v[j1] = v[j1] + d[j1] - min;
        }
        // augment
        do {
            i = pred[endofpath];
            colsol[endofpath] = i;
            j1 = endofpath;
            endofpath = rowsol[i];
            rowsol[i] = j1;
        } while (i != freerow);
    }

    // calculate cost
    double lapcost = 0;
    for (i = 0; i < dim; i++) {
        j = rowsol[i];
        u[i] = assigncost[i*dim + j] - v[j];
        lapcost += assigncost[i*dim + j];
    }

    free(free); free(collist); free(matches); free(d); free(pred);
    return lapcost;
}
```

