#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <float.h>

#define BIG FLT_MAX  // actually DBL_MAX

typedef int int_t;
typedef double cost_t;

int_t _ccrrt_dense(const int_t n, cost_t *cc, int_t *ii, int_t *jj, cost_t *u, cost_t *v) {
    int_t i, j;
    cost_t min;
    int_t *free_rows;
    int_t nfree = 0;
    int_t *matches;
    int_t num_matched = 0;
    int_t *col_matched;
    int_t *row_matched;

    free_rows = (int_t*)malloc(n * sizeof(int_t));
    matches = (int_t*)malloc(n * sizeof(int_t));
    col_matched = (int_t*)malloc(n * sizeof(int_t));
    row_matched = (int_t*)malloc(n * sizeof(int_t));

    for (i = 0; i < n; i++) {
        matches[i] = 0;
        col_matched[i] = 0;
        row_matched[i] = 0;
    }

    /* column reduction */
    for (j = n - 1; j >= 0; j--) {
        min = cc[0 * n + j];
        ii[j] = 0;
        for (i = 1; i < n; i++) {
            if (cc[i * n + j] < min) {
                min = cc[i * n + j];
                ii[j] = i;
            }
        }
        v[j] = min;
        if (++matches[ii[j]] == 1) {
            jj[ii[j]] = j;
            col_matched[j] = 1;
            row_matched[ii[j]] = 1;
            num_matched++;
        } else {
            col_matched[j] = 0;
        }
    }

    /* reduction transfer */
    for (i = 0; i < n; i++) {
        if (matches[i] == 0) {
            free_rows[nfree++] = i;
        } else if (matches[i] == 1) {
            int_t j1 = jj[i];
            min = BIG;
            for (j = 0; j < n; j++) {
                if (j != j1) {
                    cost_t d = cc[i*n+j] - v[j];
                    if (d < min) min = d;
                }
            }
            v[j1] -= min;
        }
    }

    free(free_rows); free(matches); free(col_matched); free(row_matched);
    return nfree;
}
```

