```cpp
int lap(int dim, cost_t *assigncost, col_t *rowsol, row_t *colsol, cost_t *u, cost_t *v)
{
    boolean_t unassignedfound;
    row_t i, imin, numfree = 0, prvnumfree, f, i0, k, freerow, *pred, *free;
    col_t j, j1, j2, endofpath, last, low, up, *collist, *matches;
    cost_t min, h, umin, usubmin, v2, *d;

    free = new row_t[dim];
    collist = new col_t[dim];
    matches = new col_t[dim];
    d = new cost_t[dim];
    pred = new row_t[dim];

    for (i = 0; i < dim; i++) {
        matches[i] = 0;
    }

    // column reduction
    for (j = dim; j-- > 0;) {
        min = assigncost[0 * dim + j];
        imin = 0;
        for (i = 1; i < dim; i++) {
            if (assigncost[i * dim + j] < min) {
                min = assigncost[i * dim + j];
                imin = i;
            }
        }
        v[j] = min;
        if (++matches[imin] == 1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            colsol[j] = -1;
        }
    }

    // reduction transfer
    for (i = 0; i < dim; i++) {
        if (matches[i] == 0) {
            free[numfree++] = i;
        } else if (matches[i] == 1) {
            j1 = rowsol[i];
            min = BIG;
            for (j = 0; j < dim; j++) {
                if (j != j1 && assigncost[i * dim + j] - v[j] < min) {
                    min = assigncost[i * dim + j] - v[j];
                }
            }
            v[j1] -= min;
        }
    }

    // augmenting row reduction
    for (loopcnt = 0; loopcnt < 2; loopcnt++) {
        k = 0;
        prvnumfree = numfree;
        numfree = 0;
        while (k < prvnumfree) {
            i = free[k];
            k++;
            umin = assigncost[i * dim] - v[0];
            j1 = 0;
            usubmin = BIG;
            for (j = 1; j < dim; j++) {
                h = assigncost[i * dim + j] - v[j];
                if (h < usubmin) {
                    if (h >= umin) {
                        usubmin = h;
                        j2 = j;
                    } else {
                        usubmin = umin;
                        umin = h;
                        j2 = j1;
                        j1 = j;
                    }
                }
            }
            i0 = colsol[j1];
            if (umin < usubmin) {
                v[j1] = v[j1] - (usubmin - umin);
            } else if (i0 >= 0) {
                j1 = j2;
                i0 = colsol[j1];
            }
            rowsol[i] = j1;
            colsol[j1] = i;
            if (i0 >= 0) {
                if (umin < usubmin) {
                    free[--k] = i0;
                } else {
                    free[numfree++] = i0;
                }
            }
        }
    }

    // augment solution for each free row
    for (f = 0; f < numfree; f++) {
        freerow = free[f];
        for (j = 0; j < dim; j++) {
            d[j] = assigncost[freerow * dim + j] - v[j];
            pred[j] = freerow;
            collist[j] = j;
        }
        low = 0;
        up = 0;
        unassignedfound = false;
        while (!unassignedfound) {
            if (up == low) {
                last = low - 1;
                min = d[collist[up]];
                up++;
                for (k = up; k < dim; k++) {
                    j = collist[k];
                    h = d[j];
                    if (h <= min) {
                        if (h < min) {
                            up = low;
                            min = h;
                        }
                        collist[k] = collist[up];
                        collist[up] = j;
                        up++;
                    }
                }
                for (k = low; k < up; k++) {
                    j = collist[k];
                    if (colsol[j] < 0) {
                        endofpath = j;
                        unassignedfound = true;
                        break;
                    }
                }
            }
            if (!unassignedfound) {
                j1 = collist[low];
                low++;
                i = colsol[j1];
                h = assigncost[i * dim + j1] - v[j1] - min;
                for (k = up; k < dim; k++) {
                    j = collist[k];
                    v2 = assigncost[i * dim + j] - v[j] - h;
                    if (v2 < d[j]) {
                        pred[j] = i;
                        if (v2 == min) {
                            if (colsol[j] < 0) {
                                endofpath = j;
                                unassignedfound = true;
                                break;
                            } else {
                                collist[k] = collist[up];
                                collist[up] = j;
                                up++;
                            }
                        }
                        d[j] = v2;
                    }
                }
            }
        }
        for (k = 0; k <= last; k++) {
            j1 = collist[k];
            v[j1] = v[j1] + d[j1] - min;
        }
        do {
            i = pred[endofpath];
            colsol[endofpath] = i;
            j1 = endofpath;
            endofpath = rowsol[i];
            rowsol[i] = j1;
        } while (i != freerow);
    }

    lapcost = 0;
    for (i = 0; i < dim; i++) {
        j = rowsol[i];
        u[i] = assigncost[i * dim + j] - v[j];
        lapcost += assigncost[i * dim + j];
    }

    delete[] free;
    delete[] collist;
    delete[] matches;
    delete[] d;
    delete[] pred;

    return lapcost;
}
```

