#include <stdlib.h>
#include <string.h>
#include <float.h>

void auction(int n, const double *a, int *col_of_row, double *price) {
    for (int j = 0; j < n; j++) price[j] = 0.0;
    for (int i = 0; i < n; i++) col_of_row[i] = -1;

    double maxc = 0.0;
    for (int k = 0; k < n*n; k++) if (a[k] > maxc) maxc = a[k];

    double eps = maxc / n;
    if (eps < 1e-12) eps = 1e-12;

    int *unassigned = (int*)malloc(n * sizeof(int));

    while (eps >= 1e-12) {
        int num_un = 0;
        for (int i = 0; i < n; i++) if (col_of_row[i] < 0) unassigned[num_un++] = i;

        while (num_un > 0) {
            int i = unassigned[--num_un];
            double best = DBL_MAX, second = DBL_MAX;
            int jbest = -1;
            const double *row = a + (size_t)i * n;
            for (int j = 0; j < n; j++) {
                double v = row[j] + price[j];
                if (v < best) { second = best; best = v; jbest = j; }
                else if (v < second) second = v;
            }
            double bid = second - best + eps;
            price[jbest] += bid;
            int prev = col_of_row[jbest];
            col_of_row[jbest] = i;
            if (prev >= 0) unassigned[num_un++] = prev;
        }
        eps /= 4.0;
    }
    free(unassigned);
}
EOF
